Mat Morphology_Erode(Mat twoMat) {
	Mat towMat = imread("C:/Users/16688/Desktop/123.png");
	int height = twoMat.rows;
	int width = twoMat.cols;
	Mat outMat = twoMat.clone();
	for (int y = 0; y < height; y++) {
		for (int x = 0; x < width; x++) {
			if ((x > 0) && (twoMat.at<uchar>(y, x - 1) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
			if ((y > 0) && (twoMat.at<uchar>(y - 1, x) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
			if ((x < width - 1) && (twoMat.at<uchar>(y, x + 1) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
			if ((x > 0) && (twoMat.at<uchar>(y + 1, x) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
		}
	}
	return outMat;

	imshow("test2", twoMat);
}
